/* global GDC */
(function (global) {
  'use strict';
  var GDC = global.GDC = global.GDC || {};

  // ---------------------------------------------------------------------------------------------
  // Textura de papel do fundo dos mapas (Mundo e radial, tileset hexagonal, Plantas de fase).
  // A imagem guardada é só o GRÃO (cinza neutro em 128, 512 px, emendada pra repetir); cada estilo
  // de mapa pinta o grão por cima da própria cor — então serve pro pergaminho claro e pro escuro.
  // O ladrilho colorido é calculado uma vez por cor e reaproveitado (preencher com padrão comum é
  // barato; uma mistura 'soft-light' a cada quadro pesaria em máquina modesta).
  // ---------------------------------------------------------------------------------------------

  var SRC = 'data:image/webp;base64,';
  var grain = null, grainData = null, waiting = [];
  function loadGrain() {
    if (grain) return;
    grain = new Image();
    grain.onload = function () {
      var c = document.createElement('canvas'); c.width = grain.width; c.height = grain.height;
      var x = c.getContext('2d'); x.drawImage(grain, 0, 0);
      grainData = x.getImageData(0, 0, c.width, c.height);
      var w = waiting; waiting = []; w.forEach(function (fn) { try { fn(); } catch (e) { /* ok */ } });
    };
    grain.src = SRC;
  }
  function hexRgb(hex) { var n = parseInt(String(hex).replace('#', ''), 16) || 0; return [n >> 16 & 255, n >> 8 & 255, n & 255]; }

  var tileCache = {};
  /** Ladrilho (canvas) com o grão aplicado sobre `color`. amount ≈ força do relevo (1 = padrão).
   *  null enquanto a imagem carrega; `onReady` é chamado quando ficar pronta (pra redesenhar). */
  function tile(color, amount, onReady) {
    var key = color + '|' + amount;
    if (tileCache[key]) return tileCache[key];
    if (!grainData) { loadGrain(); if (onReady) waiting.push(onReady); return null; }
    var rgb = hexRgb(color), lum = (0.299 * rgb[0] + 0.587 * rgb[1] + 0.114 * rgb[2]) / 255;
    // em papel escuro o mesmo relevo "grita" mais — reduz um pouco
    var k = (amount == null ? 1 : amount) * (0.55 + 0.45 * lum) * 1.2;
    var c = document.createElement('canvas'); c.width = grainData.width; c.height = grainData.height;
    var x = c.getContext('2d'), out = x.createImageData(c.width, c.height), s = grainData.data, d = out.data;
    for (var i = 0; i < s.length; i += 4) {
      var g = (s[i] - 128) * k;
      d[i] = rgb[0] + g; d[i + 1] = rgb[1] + g; d[i + 2] = rgb[2] + g; d[i + 3] = 255;
    }
    x.putImageData(out, 0, 0);
    return (tileCache[key] = c);
  }
  /** Padrão pronto pra `ctx`, com escala `scale` (px de tela por px do ladrilho) e origem (ox, oy) —
   *  quem chama prende o padrão às coordenadas do mapa, pro grão andar junto ao arrastar. */
  function pattern(ctx, color, amount, scale, ox, oy, onReady) {
    var t = tile(color, amount, onReady);
    if (!t) return null;
    var p = ctx.createPattern(t, 'repeat');
    if (p && p.setTransform && typeof DOMMatrix !== 'undefined') p.setTransform(new DOMMatrix([scale, 0, 0, scale, ox || 0, oy || 0]));
    return p;
  }
  loadGrain();

  GDC.paperTexture = { tile: tile, pattern: pattern };
}(window));
